import React, { useState } from 'react'; 
import EliminarUsuario from './Eliminar';

const TablaUsuarios = ({ usuarios, actualizarUsuario }) => {
    const [usuarioSeleccionado, setUsuarioSeleccionado] = useState(null);

    const empezarEdicion = (usuario) => setUsuarioSeleccionado(usuario);
    const manejarCambio = (e) => {
        const { name, value } = e.target;
        setUsuarioSeleccionado((prev) => ({ ...prev, [name]: value }));
    };
    const manejarEnvio = (e) => {
        e.preventDefault();
        actualizarUsuario(usuarioSeleccionado);
        setUsuarioSeleccionado(null);
    };

    return (
        <div>
            <h2>Lista de Usuarios</h2>
            <table>
                <thead>
                    <tr>
                        <th>Nombre de Usuario</th>
                        <th>Nombre</th>
                        <th>Apellido</th>
                        <th>Fecha de Nacimiento</th>
                        <th>Acciones</th>
                    </tr>
                </thead>
                <tbody>
                    {usuarios.map((usuario) => (
                        <tr key={usuario.id}>
                            <td>{usuario.username}</td>
                            <td>{usuario.name}</td>
                            <td>{usuario.surname}</td>
                            <td>{usuario.birthDate}</td>
                            <td>
                                <button onClick={() => empezarEdicion(usuario)}>Modificar</button>
                                <EliminarUsuario usuarioId={usuario.id} />
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            {usuarioSeleccionado && (
                <form onSubmit={manejarEnvio}>
                    <h2>Modificar Usuario</h2>
                    <label>
                        Nombre de Usuario:
                        <input type="text" name="username" value={usuarioSeleccionado.username} onChange={manejarCambio} />
                    </label>
                    <label>
                        Apellido:
                        <input type="text" name="surname" value={usuarioSeleccionado.surname} onChange={manejarCambio} />
                    </label>
                    <label>
                        Fecha de Nacimiento:
                        <input type="date" name="birthDate" value={usuarioSeleccionado.birthDate} onChange={manejarCambio} />
                    </label>
                    <button type="submit">Guardar Cambios</button>
                    <button type="button" onClick={() => setUsuarioSeleccionado(null)}>Cancelar</button>
                </form>
            )}
        </div>
    );
};

export default TablaUsuarios;
